from pathlib import Path
from datetime import datetime,timezone
from itertools import combinations,product
import json
root=Path(__file__).resolve().parent;viewports=[[1280,720],[320,568],[390,844],[844,390]];edges=[[.5,320],[480,.5],[959.5,320],[480,639.5]];rows=[]
for i,viewport in enumerate(viewports):
    for j,size in enumerate([1,96]):rows.append(dict(id='e'+str(len(rows)+1),viewport=viewport,size=size,strength=.15 if (i+j)%2==0 else 1,edge=edges[i],long_hold=False))
proof=[];levels=dict(viewport=viewports,size=[1,96],strength=[.15,1]);key=lambda v:json.dumps(v)
for a,b in combinations(levels,2):
    assert {(key(r[a]),key(r[b])) for r in rows}=={(key(x),key(y)) for x,y in product(levels[a],levels[b])};proof.append(dict(factors=[a,b],pairs=len({(key(r[a]),key(r[b])) for r in rows})))
for i,viewport in enumerate(viewports):rows.append(dict(id='m'+str(i+1),viewport=viewport,size=22,strength=1,edge=edges[i],long_hold=True))
cancel=[dict(id=mode+'-'+str(i+1),viewport=viewport,size=22,strength=1,mode=mode,hold_ms=180 if mode=='touch-cancel' else 1200) for i,viewport in enumerate(viewports) for mode in ['touch-cancel','blur-cancel']]
for kind,case,factor,pad in [('mist','PAINT-010',2.6,4),('splatter','PAINT-011',2.8,12),('confetti','PAINT-012',2.8,6)]:
    file=root/('fixtures/'+case+'-plan.json');assert not file.exists(),'Keep each pre-execution plan'
    plan=dict(at=datetime.now(timezone.utc).isoformat(),case=case,applicator=kind,status='Pre-execution plan, not a result',rows=rows,cancellation_rows=cancel,extreme_pairwise_proof=proof,main='Fresh960x640 white PLAY. Each row: stationary150ms, optional main1200ms hold, moving41 samples320,320 to640,320, then150ms at the declared half-cell edge. Confetti uses Rainbow first and an additional actual Red burst, preserving the older pixels. Every gesture gets actual project/PNG, separate Undo/Redo and fresh input.',capture='Public paint-canvas captures after two real frames while held, after actual hold, then two frames after release and250ms later. No file control is operated while a pointer is held. All gesture/event/elapsed data retained; no fake clock or random generator override.',cancellation='Separate fresh context for each row. Chrome-native emulated touchStart/touchCancel generates trusted pointercancel after180ms; this is software emulation, not physical device certification. A separate1200ms mouse hold is cancelled by actually activating another tab of the same isolated headless context; return with button still held and verify no resumed deposit before cleanup mouse-up. Observe native blur/visibility events. No user browser/profile/desktop access.',footprint=dict(radius_factor=factor,radius_padding=pad,stationary=[480,320],moving=[[320,320],[640,320]]),oracle='Independent affected masks and point/segment distances, actual all-four-edge clipped boundary pixels and no opposite-edge wrap. Stationary first/late frames must show additional pigment without displaced pointer events; released/cancelled frames must stop changing after render acknowledgement. Known Red updates lie on the source-over segment from previous pixel to Red within2/255, including Red over existing Rainbow. Main full-Strength Confetti has >=3 distinct chromatic hue bins. Each style is inspected separately; large-size stationary radius90 must exceed eight times minimum-size radius90, with source dimensions unchanged. Splatter main has an independently measured connected drop component >=30px. Every history/fresh source/RGBA exact; all actual downloads hashed. Unseeded random arrangements are measured, never compared to invented expected pixels.',scope='12 positive main/extreme rows plus8 software cancellation rows per actual spray applicator; every named style, all four edges/layouts, min/max/intermediate size and both Strength endpoints. Physical pen/touch and AT remain separate unverified scope.')
    file.write_text(json.dumps(plan,indent=2)+'\n',encoding='utf-8')
print('Recorded three complete spray plans:36 main/extreme rows and24 software cancellation rows, all named styles/edges/layouts.')
